ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	method: "GET",
	path: "/countries/v5/code",
	queryParams: {
		q: vars.record.country_code
	}
}

ee:message.ee:set-payload:
%dw 2.0
output application/json

var country = (payload.data.objects filter $.codes.alpha_2 == vars.record.country_code)[0] default {}
---
{
    country_name: country.names.common,
    region: country.region
}

ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	method: "GET",
	path: "/rates",
	queryParams: {
		base: vars.record.currency,
		quotes: Mule::p("referenceCurrency")
	}
}

ee:message.ee:set-payload:
%dw 2.0 output application/json
var rate = payload[0]
--- { fx_rate: rate.rate, amount_eur: if(!isEmpty(rate.rate)) vars.record.amount_local as Number * rate.rate else null }
